// Shared fixtures for the parity tests. web/tests/golden/ and web/dist/data/
// are generated by `python export_web.py --golden` from the Python pipeline.
import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { RawImage } from "@huggingface/transformers";
import { expandCatalog } from "../js/catalog.js";
import { decodeF16 } from "../js/search.js";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
export const GOLDEN = here("./golden/");
export const DATA = here("../dist/data/");

if (!existsSync(GOLDEN + "golden.json") || !existsSync(DATA + "manifest.json")) {
  throw new Error("Golden set missing. Run `python export_web.py --golden` first.");
}

const json = (path) => JSON.parse(readFileSync(path, "utf-8"));
export const golden = json(GOLDEN + "golden.json");
export const manifest = json(DATA + "manifest.json");
export const items = expandCatalog(json(DATA + "catalog.json"));
export const byRow = [];
for (const item of items) if (item.row >= 0) byRow[item.row] = item.name;
export const rowOf = Object.fromEntries(items.map((i) => [i.name, i.row]));

export const matrix = (name) => decodeF16(readFileSync(DATA + name).buffer.slice(0));

/** Decodes a PNG into the {width, height, channels, data} shape the browser code uses. */
export async function loadImage(file) {
  const r = await RawImage.read(GOLDEN + file);
  return { width: r.width, height: r.height, channels: r.channels, data: new Uint8ClampedArray(r.data) };
}

export const cosine = (a, b) => a.reduce((s, v, i) => s + v * b[i], 0);
export const overlap = (a, b) => a.filter((x) => b.includes(x)).length;
